import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { IToolbarItem } from './../../ricos-types/index.js';
import { ToolbarButton } from './../../_shared/toolbar-button/toolbar-button.js';

export const RemoveLinkButton = ({ toolbarItem }: { toolbarItem: IToolbarItem }) => {
  const { t } = useContext(RicosContext);

  //TODO: move translation to toolbar entity and use entity here
  const tooltip = t(toolbarItem.presentation?.tooltip);
  const dataHook = toolbarItem.presentation?.dataHook;

  return (
    <ToolbarButton
      tooltip={tooltip}
      onClick={() => {
        toolbarItem.commands.click();
      }}
      prefix={toolbarItem.presentation?.icon}
      dataHook={dataHook}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
