import { Link, LinkSmall } from '@wix/wix-ui-icons-common/lazy';
import React from 'react';

import { RICOS_ANCHOR_TYPE, RICOS_LINK_TYPE } from './../ricos-content/index.js';
import type { EditorPluginCreator, PublicCommands } from './../ricos-types/index.js';
import {
  Decoration_Type,
  RicosPluginToolbarNames,
  createShortcut,
  quickActionsModalSections,
} from './../ricos-types/index.js';
import { openLinkModal } from './../_shared/link-modal/open-link-modal.js';
import { toggleLinkModal } from './../_shared/link-modal/toggle-link-modal.js';
import type { NamedLink } from './../_shared/link/types.js';
import { isAlwaysVisible } from './../_shared/resolvers/is-always-visible.js';
import { isLinkOrAnchorInText } from './../_shared/resolvers/is-link-or-anchor-in-text.js';
import { isNodeSelected } from './../_shared/resolvers/is-node-selected.js';
import type { Selection } from './../tiptap/pm/state.js';
import { LinkButton } from './../toolbars-v3/index.js';

import { anchorConverter } from './anchor-converter.js';
import { autolinkExtension } from './autolink-extension.js';
import { TEXT_BUTTON_LINK } from './data-hooks.js';
import { DEFAULTS } from './defaults.js';
import { getToolbarButtons } from './get-toolbar-buttons.js';
import { linkConverter } from './link-converter.js';
import type { LinkPluginEditorConfig } from './types.js';
import { LINK_TYPE } from './types.js';

const onSave = (publicCommands: PublicCommands) => (linkData: NamedLink) => {
  publicCommands.insertDecoration(linkData.anchor ? RICOS_ANCHOR_TYPE : RICOS_LINK_TYPE, linkData);
};

const onSaveMultiple = (publicCommands: PublicCommands) => (anchors: NamedLink[]) => {
  publicCommands.insertMultipleAnchors(anchors);
};

const onUnlink = (publicCommands: PublicCommands) => (linkData: NamedLink) => {
  publicCommands.deleteDecoration(linkData.anchor ? RICOS_ANCHOR_TYPE : RICOS_LINK_TYPE);
};

export const pluginLink: EditorPluginCreator<LinkPluginEditorConfig> = config => {
  const pluginConfig = { type: 'link' as const, ...DEFAULTS.config, ...config };
  const { enabledLinkTypes } = pluginConfig;

  return {
    config: pluginConfig,
    type: LINK_TYPE,
    tiptapExtensions: [autolinkExtension],
    pmNodeConverters: [],
    pmMarkConverters: [linkConverter, anchorConverter],
    shortcuts: [
      createShortcut({
        name: Decoration_Type.LINK,
        description: 'ShortcutsSheet_Formatting_Link',
        group: 'ShortcutsSheet_Section_Formatting',
        keys: {
          macOs: 'Meta+K',
          windows: 'Ctrl+K',
        },
        enabled: true,
        showInShortcutSheet: true,
        command: ({ publicCommands, modalService, editor }) => {
          openLinkModal({
            editor,
            initialValue: publicCommands.getLinkDataInSelection(),
            modalService,
            onSave: onSave(publicCommands),
            onSaveMultiple: onSaveMultiple(publicCommands),
            onUnlink: onUnlink(publicCommands),
            placement: 'bottom-start',
            enabledLinkTypes,
            returnFocusToEditor: true,
          });
          return 'continue';
        },
      }),
    ],
    toolbar: {
      names: [RicosPluginToolbarNames.LINK],
      getButtons: getToolbarButtons,
      isVisible: (selection, editor) => {
        const isSelectionCollapsed = (selection: Selection): boolean => {
          const { from, to } = selection;
          return to - from <= 0;
        };
        const isCollapsed = isSelectionCollapsed(selection);
        const isLinkInSelection = editor.getPublicCommands().hasLinkInSelection();
        return isCollapsed && isLinkInSelection;
      },
    },
    textButtons: [
      {
        id: Decoration_Type.LINK,
        type: 'modal',
        presentation: {
          dataHook: TEXT_BUTTON_LINK,
          tooltip: 'TextLinkButton_Tooltip',
          icon: Link,
          renderer: toolbarItem => <LinkButton toolbarItem={toolbarItem} />,
        },
        attributes: {
          visible: isAlwaysVisible,
          active: isLinkOrAnchorInText,
          disabled: isNodeSelected,
        },
        Component: LinkButton,
        command:
          ({ publicCommands, modalService, referenceElement }) =>
          () => {
            toggleLinkModal({
              initialValue: publicCommands.getLinkDataInSelection(),
              modalService,
              onSave: onSave(publicCommands),
              onSaveMultiple: onSaveMultiple(publicCommands),
              onUnlink: onUnlink(publicCommands),
              referenceElement,
              enabledLinkTypes,
              returnFocusToEditor: true,
            });
            return true;
          },
      },
    ],
    getQuickActions: ({ pluginServices }) => [
      {
        id: 'link',
        title: 'QuickActionsPlugin_ActionTitle_Link',
        icon: pluginServices?.context.isMobile ? Link : LinkSmall,
        section: quickActionsModalSections.FormatLayout,
        tags: ['link', 'anchor', 'url', 'hyperlink'],
        command: ({ publicCommands, modalService, editor }) => {
          openLinkModal({
            editor,
            modalService,
            onSaveMultiple: onSaveMultiple(publicCommands),
            onSave: onSave(publicCommands),
            onUnlink: onUnlink(publicCommands),
            placement: 'bottom-start',
            enabledLinkTypes,
            returnFocusToEditor: true,
          });
        },
      },
    ],
  };
};
