import { Newspaper, Unlink } from '@wix/wix-ui-icons-common/lazy';
import React from 'react';

import { RICOS_ANCHOR_TYPE, RICOS_LINK_TYPE } from './../ricos-content/index.js';
import type { RicosServices, ToolbarButton } from './../ricos-types/index.js';
import { LINK_MODAL_ID } from './../_shared/link-modal/constants.js';
import { toggleLinkModal } from './../_shared/link-modal/toggle-link-modal.js';
import { createSettingsButton } from './../_shared/plugin-toolbar/create-settings-button.js';
import { createSeparator } from './../_shared/plugin-toolbar/separator/create-separator.js';
import { createUrlLinkButton } from './../_shared/plugin-toolbar/url-link-button/create-url-link-button.js';
import { getAnchorData } from './../_shared/resolvers/get-anchor-data.js';
import { getUrlLinkData } from './../_shared/resolvers/get-url-link-data.js';
import { isAlwaysVisible } from './../_shared/resolvers/is-always-visible.js';
import { isAnchorInText } from './../_shared/resolvers/is-anchor-in-text.js';
import { isLinkInText } from './../_shared/resolvers/is-link-in-text.js';
import { isLinkPreviewEnabled } from './../_shared/resolvers/is-link-preview-enabled.js';

import {
  LINK_PLUGIN_DISPLAY_AS_LINK_PREVIEW_BUTTON,
  LINK_PLUGIN_REMOVE_BUTTON,
  LINK_PLUGIN_SCROLL_TO_ANCHOR_BUTTON,
} from './data-hooks.js';
import { AnchorLinkButton, AnchorLinkLabel } from './toolbar/anchor-link-button.js';
import { DisplayLinkPreview } from './toolbar/display-link-preview-button.js';
import { RemoveLinkButton } from './toolbar/remove-link-button.js';
import type { LinkPluginEditorConfig } from './types.js';

export const getToolbarButtons = (
  _config: LinkPluginEditorConfig,
  services: RicosServices
): ToolbarButton[] => {
  const anchorLink: ToolbarButton = {
    id: 'anchorLink',
    type: 'toggle',
    dataHook: LINK_PLUGIN_SCROLL_TO_ANCHOR_BUTTON,
    attributes: {
      visible: isAnchorInText,
      selectedAnchorLinkData: getAnchorData,
    },
    tooltip: null,
    icon: () => <AnchorLinkLabel t={services.t} />,
    command: ({ tiptapEditor, attributes: { selectedAnchorLinkData } }) => {
      tiptapEditor.commands.scrollToAnchor(selectedAnchorLinkData);
    },
    renderer: toolbarItem => <AnchorLinkButton toolbarItem={toolbarItem} />,
  };

  const urlLink: ToolbarButton = createUrlLinkButton({
    services,
    attributes: {
      visible: isLinkInText,
      selectedUrlLinkData: getUrlLinkData,
    },
  });

  const displayLinkPreview: ToolbarButton = {
    id: 'displayLinkPreview',
    type: 'toggle',
    dataHook: LINK_PLUGIN_DISPLAY_AS_LINK_PREVIEW_BUTTON,
    tooltip: 'LinkPanelContainer_DisplayAsLinkPreview',
    icon: Newspaper,
    attributes: {
      visible: isLinkPreviewEnabled,
    },
    command: ({ tiptapEditor }) => {
      tiptapEditor.commands.createLinkPreview();
    },
    renderer: toolbarItem => <DisplayLinkPreview toolbarItem={toolbarItem} />,
  };

  const separator1 = createSeparator({
    visible: isAlwaysVisible,
  });

  const settings = createSettingsButton({
    modalId: LINK_MODAL_ID,
    command: ({ publicCommands, referenceElement, modals }) => {
      toggleLinkModal({
        initialValue: publicCommands.getLinkDataInSelection(),
        modalService: modals,
        onSave: link => {
          publicCommands.insertDecoration(link.anchor ? RICOS_ANCHOR_TYPE : RICOS_LINK_TYPE, link);
        },
        onUnlink: link => {
          publicCommands.deleteDecoration(link.anchor ? RICOS_ANCHOR_TYPE : RICOS_LINK_TYPE);
        },
        referenceElement,
        returnFocusToEditor: true,
        onClickOutside: {
          on: 'pointerup',
          handler: e => {
            if (!referenceElement?.contains?.(e.target as Node)) {
              modals.closeModal(LINK_MODAL_ID);
              return;
            }
          },
        },
      });
    },
  });

  const separator2 = createSeparator({
    visible: isAlwaysVisible,
  });

  const removeLink: ToolbarButton = {
    id: 'removeLink',
    type: 'toggle',
    dataHook: LINK_PLUGIN_REMOVE_BUTTON,
    tooltip: 'LinkPanelContainer_RemoveButton',
    icon: Unlink,
    attributes: {
      visible: isLinkInText,
    },
    command: ({ tiptapEditor }) => {
      tiptapEditor.chain().focus().unsetLink().run();
    },
    renderer: toolbarItem => <RemoveLinkButton toolbarItem={toolbarItem} />,
  };

  const removeAnchor: ToolbarButton = {
    id: 'removeAnchor',
    type: 'toggle',
    dataHook: LINK_PLUGIN_REMOVE_BUTTON,
    tooltip: 'LinkPanelContainer_RemoveButton',
    icon: Unlink,
    attributes: {
      visible: isAnchorInText,
    },
    command: ({ tiptapEditor }) => {
      tiptapEditor.chain().focus().unsetAnchor().run();
    },
    renderer: toolbarItem => <RemoveLinkButton toolbarItem={toolbarItem} />,
  };
  if (services.context.environment === 'wixel') {
    return [anchorLink, urlLink, settings, displayLinkPreview, removeLink, removeAnchor];
  }

  return [
    anchorLink,
    urlLink,
    separator1,
    displayLinkPreview,
    settings,
    separator2,
    removeLink,
    removeAnchor,
  ];
};
