import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { IToolbarItem } from './../../ricos-types/index.js';
import { ToolbarButton } from './../../_shared/toolbar-button/toolbar-button.js';

export const DisplayLinkPreview = ({ toolbarItem }: { toolbarItem: IToolbarItem }) => {
  const { t } = useContext(RicosContext);

  return (
    <ToolbarButton
      active={toolbarItem.attributes.active}
      tooltip={t(toolbarItem.presentation?.tooltip)}
      onClick={() => {
        toolbarItem.commands.click();
      }}
      prefix={toolbarItem.presentation?.icon}
      dataHook={toolbarItem.presentation?.dataHook}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
