import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { DEFAULTS } from './defaults.js';
import { nodeViewDecorators } from './nodeViewDecorators/index.js';
import type { LinkPluginViewerConfig } from './types.js';
import { LINK_TYPE } from './types.js';

export const pluginLink: ViewerPluginCreator<LinkPluginViewerConfig> = config => {
  return {
    config: { ...DEFAULTS.config, ...config },
    type: LINK_TYPE,
    nodeViewDecorators,
  };
};
