import type { PmMarkConverter } from './../pm-converters/types.js';
import type { AnchorData, AnchorDecoration } from './../ricos-schema/next-schema/index.js';
import { Decoration_Type } from './../ricos-schema/next-schema/index.js';

export const anchorConverter: PmMarkConverter = {
  fromPm: {
    type: Decoration_Type.ANCHOR,
    convert: mark => {
      const { attrs } = mark;
      return [
        {
          type: Decoration_Type.ANCHOR,
          anchorData: { ...attrs } as AnchorData,
        },
      ];
    },
  },
  toPm: {
    type: Decoration_Type.ANCHOR,
    convert: decoration => {
      const { anchorData } = decoration as AnchorDecoration;
      return {
        type: Decoration_Type.ANCHOR,
        attrs: { ...anchorData },
      };
    },
  },
};
